public class JSearchArrayTotalCounts {
	//Paso 1: Definir el metodo 
	public static void searchArrays(double[] lst1, double[] lst2) {
		//Paso 1.1: Iterar por los valores en el segundo arreglo
		int count = 0;
		for (double val2 : lst2) {
			//Paso 1.1.1: Iterar por los valores en el primer arreglo
			for (double val1 : lst1) {
				//Paso 1.1.1.1: Incrementar el numero de coincidencias si encontramos una coincidencia
				if (val1 == val2) {
					count += 1;
				}
			}
		}
		System.out.println("El numero total de veces que los elementos del segundo arreglo aparecen en el primer arreglo es " + count);   
	}
	public static void main(String[] args) {
		double[] values1 = {2.0, 11, 4, 5, 3, 3.5, 4, 10, 16, 3};
		double[] values2 =  {7, 11, 3, 1.0};
		searchArrays(values1, values2);
	}
}

